status.css:
*{box-sizing:border-box;margin:0;padding:0}
.hud{font-family:"Courier New",Courier,monospace;width:100%;background:#1e1e12;border:1px solid #4a4a2a;border-radius:3px;overflow:hidden;color:#a8a880;box-shadow:0 0 0 1px rgba(0,0,0,.7),0 6px 20px rgba(0,0,0,.7)}
.hud-header{background:#141410;border-bottom:1px solid #4a4a2a;display:flex}
.hud-hname{flex:1;padding:8px 12px;border-right:1px solid #3a3a22}
.hud-hlabel{font-size:9px;color:#4a4a30;letter-spacing:2px;margin-bottom:3px}
.hud-hval{font-size:13px;font-weight:700;color:#e0d090;letter-spacing:.5px}
.hud-hloc{padding:8px 12px;display:flex;flex-direction:column;justify-content:center;align-items:flex-end;gap:3px}
.hud-hlocl{font-size:9px;color:#4a4a30;letter-spacing:2px}
.hud-hlocv{font-size:11px;color:#c09000;font-weight:700;letter-spacing:.5px}
.hud-trifold{display:flex;border-bottom:1px solid #3a3a22}
.hud-cell{flex:1;padding:8px 10px;border-right:1px solid #2a2a18}
.hud-cell:last-child{border-right:none}
.hud-clabel{font-size:9px;color:#4a4a30;letter-spacing:1.5px;margin-bottom:5px}
.hud-cval{font-size:11px;color:#c8c8a0;font-weight:600;line-height:1.4;overflow-wrap:break-word;word-break:keep-all}
.hud-csub{font-size:10px;color:#6a6a50;margin-top:2px;overflow-wrap:break-word;word-break:keep-all}
.hud-threat{display:flex;align-items:center;background:#252518;border-bottom:1px solid #3a3a22;padding:6px 12px;gap:10px}
.hud-tlabel{font-size:9px;color:#4a4a30;letter-spacing:2px;flex:none}
.hud-tline{flex:1;height:1px;background:#3a3a22}
.hud-tval{font-size:12px;font-weight:700;color:#1a1a08;background:#c09000;padding:2px 14px;letter-spacing:2px}
.hud-tline2{flex:1;height:1px;background:#3a3a22}
.hud-rapport{padding:8px 12px;border-bottom:1px solid #3a3a22;background:#1a1a10}
.hud-rhead{display:flex;justify-content:space-between;font-size:9px;color:#4a4a30;letter-spacing:1.5px;margin-bottom:5px}
.hud-rpct{color:#c09000;font-weight:700;font-size:11px}
.hud-rtrack{height:4px;background:#141410;border:1px solid #2a2a18;margin-bottom:3px;position:relative}
.hud-rfill{height:100%;background:#c09000}
.hud-rtick{display:flex;justify-content:space-between;font-size:9px;color:#2a2a18}
.hud-note{background:#141410;padding:7px 12px;display:flex;gap:8px;align-items:flex-start;border-bottom:1px solid #2a2a18}
.hud-ntag{font-size:9px;color:#c09000;letter-spacing:1.5px;flex:none;padding-top:1px}
.hud-ntext{font-size:11px;color:#6a6a50;line-height:1.5;overflow-wrap:break-word;word-break:keep-all}
.hud-input-row{display:flex;align-items:center;gap:0;background:#0e0e0a;padding:6px 8px;border-top:1px solid #2a2a18}
.hud-input{flex:1;background:transparent;border:1px solid #3a3a22;color:#c8c8a0;font-family:"Courier New",Courier,monospace;font-size:11px;padding:4px 8px;outline:none;letter-spacing:.5px}
.hud-input::placeholder{color:#3a3a28}
.hud-input:focus{border-color:#c09000}
.hud-send{background:#c09000;color:#1a1a08;border:none;font-family:"Courier New",Courier,monospace;font-size:10px;font-weight:700;letter-spacing:1.5px;padding:5px 12px;cursor:pointer;flex:none;margin-left:4px}

