/* == 전술 HUD 골드 · 윈도우 테마 == */
#us-float, #us-prompt-bubble-window {
  border-radius: 3px;
  box-shadow: 0 0 0 1px rgba(0,0,0,.7), 0 6px 20px rgba(0,0,0,.7);
  --us-float-bg: #1e1e12;
  --us-float-fg: #a8a880;
  --us-float-border: #4a4a2a;
  --us-float-muted: #6a6a50;
  --us-float-primary: #c09000;
  --us-float-primary-fg: #1a1a08;
  --us-float-secondary: #242418;
  --us-float-accent: #2a2a18;
}
#us-float .us-f-title,
#us-float .us-tab,
#us-float .us-scene-button {
  font-family: "Courier New", Courier, monospace;
  letter-spacing: .5px;
}
.us-box {
  --us-box-bg: #1e1e12;
  --us-box-fg: #a8a880;
  --us-box-border: #4a4a2a;
  --us-box-muted: #6a6a50;
  --us-box-input-bg: #141410;
  --us-box-secondary: #242418;
  --us-box-accent: #2a2a18;
  --us-box-primary: #c09000;
  --us-box-primary-fg: #1a1a08;
  --us-box-switch-off: #4a4a2a;
  --us-box-switch-on: #c09000;
  --us-box-switch-thumb: #1e1e12;
}
